        Require ([guid]$source.Guid-eq[guid]'1b191872-c372-41ee-a416-e18863996f54'-and$source.Size-eq64GB-and$source.IsOffline-and-not$source.IsReadOnly-and-not$source.IsBoot-and-not$source.IsSystem-and[guid]$sp.Guid-eq[guid]'f06075a8-67a2-46b9-8fac-4af4da809617'-and$sp.Offset-eq16MB-and$sp.Size-eq52GB-and$b.disk_number-eq6-and[guid]$b.identity.disk_guid-eq[guid]'c8ac8d6e-5a5e-4818-bba1-d399f5a8b38b'-and[guid]$shadow.Guid-eq[guid]$b.identity.disk_guid-and$shadow.Size-eq$b.identity.disk_bytes-and$shadow.IsOffline-and$shadow.IsReadOnly-and-not$shadow.IsBoot-and-not$shadow.IsSystem-and[guid]$rp.Guid-eq[guid]$b.identity.partition_guid-and$rp.Offset-eq32MB-and$rp.Size-eq52GB-and$b.identity.partition_bytes-eq52GB-and$b.identity.logical_sector_bytes-eq512-and$b.identity.physical_sector_bytes-eq4096-and(Get-Partition -DriveLetter C).DiskNumber-eq0) 'Actual source1 OFFLINE1/new c8 shadow6 OFFLINE|READ_ONLY3 and OS0 are required.'
