        Require ([guid]$g.Guid-eq[guid]'e1f3b9d3-979f-4123-9fee-399640c25092'-and-not$g.IsOffline-and-not$g.IsReadOnly-and$gp.DiskNumber-eq4-and[guid]$gp.Guid-eq[guid]'21445e3a-b435-4978-ba01-2ae217f66f6a'-and$gv.FileSystem-ceq'ReFS'-and$gv.AllocationUnitSize-eq4096-and[guid]$oldShadow.Guid-eq[guid]'ad077674-6305-4767-a2aa-6ded3b707e36'-and$oldShadow.IsOffline-and$oldShadow.IsReadOnly) 'Preserved G4/shadow5 metadata differs.'
