    Import-Module (Join-Path $PSScriptRoot 'Lab.psm1') -Force;$config=Get-LabConfiguration -WorkspaceRoot $workspace;$capacity=Get-LabCapacity -Configuration $config;Need ($capacity.MaximumActualBytes-eq329374052988-and$capacity.MinimumFreeBytes-eq17179869184) 'Fixed50GB epoch/16GiB floor differs.';Assert-LabCapacity -Capacity $capacity -AdditionalBytes 512MB
    $null=HostGuard 'Running';$phase='terminal-and-closed-metadata';$session=New-PSSession -VMId $id -Credential (Import-Clixml (Join-Path $workspace '.lab\hyperv\win11\secrets\guest-credential.xml')) -ErrorAction Stop;$dispatchJson=$d|ConvertTo-Json -Depth 10 -Compress
    $record=Invoke-Command -Session $session -ScriptBlock $observe -ArgumentList $dispatchJson,$true,''|ConvertFrom-Json
    $null=New-Item -ItemType Directory -Path $root -ErrorAction Stop;$created=$true;Save 'preservation-intent.json' @{schema_version=1;kind='bundle-cli-partial-preservation-intent';run_id=$run;vm_id=$id.ToString('D');parent_id=$parent.ToString('D');prior_checkpoint_ids=$old;original_dispatch_path=[IO.Path]::GetFullPath($OriginalDispatchPath);original_dispatch_sha256=$OriginalDispatchSha256;terminal=$record|Select-Object -Property * -ExcludeProperty documents;capacity=$capacity;forecast_bytes=512MB;script_sha256=(Get-FileHash -LiteralPath $PSCommandPath).Hash.ToLowerInvariant();automatic_retry=$false;raw_recovery_authorized=$false;utc=[DateTime]::UtcNow.ToString('o')}
    $archive=Join-Path $root 'closed-metadata';$null=New-Item -ItemType Directory -Path $archive -ErrorAction Stop;$pins=@();$publicationBytes=$null;$bundleBytes=$null;$managedBytes=$null;$total=[long]0
    foreach($doc in $record.documents){Need ($doc.name-cmatch'\A[a-z-]+(?:\.stdout|\.stderr)?\.(?:json|log)\z') 'Invalid archived metadata/log leaf.';$bytes=[Convert]::FromBase64String($doc.bytes_base64);$total+=$bytes.Length;Need ($bytes.Length-eq$doc.bytes-and$total-le16MB-and(Digest $bytes)-ceq$doc.sha256) 'Transported closed metadata/log pin differs.';SaveBytes (Join-Path $archive $doc.name) $bytes;$pins+=@{name=$doc.name;source=$doc.source;bytes=$doc.bytes;sha256=$doc.sha256};switch -CaseSensitive ($doc.name){'bundle-publication.json'{$publicationBytes=$bytes};'compact-recovery-bundle.json'{$bundleBytes=$bytes};'managed-shadow.json'{$managedBytes=$bytes}}}
